-- Describe retained grants from their owning resource registry; no grants change.
-- One selectable unit per existing canonical grant, including preserved scopes.
create or replace function feedx_integrations.business_capability_catalog(p_identity uuid) returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
select coalesce(jsonb_agg(v||jsonb_build_object('label',coalesce((select r.label from feedx_integrations.resources r where r.key=v->>'resource_key'),regexp_replace(v->>'label','^Preserved ','')),'workspace',coalesce(v->>'workspace','Factory'),'domain',case when v->>'section'='Factory' then case v->>'module_id' when 'factory_dashboard' then 'Factory Insights' when 'factory_product_feedback' then 'Product Feedback' when 'factory_petty_cash' then 'Petty Cash' else 'Production' end else coalesce(v->>'section',v->>'domain_label','MeSTI') end,'scope',coalesce((select jsonb_agg(jsonb_build_object('resource',r.slug,'label',r.label,'row_scope',b.row_scope,'fields',b.allowed_fields,'relationships',b.relationship_modules,'required_modules',b.required_modules)) from feedx_integrations.navigation_resources b join feedx_integrations.resources r on r.key=b.resource_key where b.module_id=v->>'module_id'),jsonb_build_array(coalesce((select jsonb_build_object('resource',r.slug,'label',r.label,'scope_note',r.description,'field_policy',r.field_policy) from feedx_integrations.resources r where r.key=v->>'resource_key'),jsonb_build_object('resource',v->>'resource_key','label',v->>'label','scope_note',v->>'description')))),'retained_only',v->>'module_id' is null) order by v->>'workspace',v->>'label'),'[]')
from (select value v from jsonb_array_elements(feedx_integrations.navigation_catalog(p_identity)) union all select value from jsonb_array_elements(feedx_integrations.preserved_access(p_identity)))s;
$$;
